// Validate request, rate-limit per visitor, serve from cache when possible.
// Output: { response } to answer right away, or { viatorBody, ... } to call Viator.
// Cache and rate-limit counters live in workflow static data, which n8n only
// persists for production (active) executions, not manual test runs.

// ── CONFIG ───────────────────────────────────────────────────────
const LIMIT_PER_IP = 30;                 // price lookups per visitor...
const WINDOW_MS    = 10 * 60 * 1000;     // ...per 10 minutes
const CACHE_MS     = 6 * 60 * 60 * 1000; // reuse a search result for 6 hours
const CACHE_MAX    = 500;                // max cached searches kept
const CURRENCIES   = ['USD', 'EUR', 'GBP', 'CAD', 'AUD', 'MXN', 'JPY'];
// ─────────────────────────────────────────────────────────────────

const store = $getWorkflowStaticData('global');
store.cache = store.cache || {};
store.hits = store.hits || {};

const req = $input.first().json || {};
const body = req.body || {};
const headers = req.headers || {};
const now = Date.now();
const reply = (response) => [{ json: { response } }];

// Prune old counters and expired cache entries.
for (const ip of Object.keys(store.hits)) {
  store.hits[ip] = store.hits[ip].filter((t) => now - t < WINDOW_MS);
  if (!store.hits[ip].length) delete store.hits[ip];
}
for (const k of Object.keys(store.cache)) {
  if (now - store.cache[k].at > CACHE_MS) delete store.cache[k];
}

// Rate limit by visitor IP.
const ip = String(
  headers['cf-connecting-ip'] ||
  String(headers['x-forwarded-for'] || '').split(',')[0] ||
  'unknown'
).trim();
const hits = store.hits[ip] || [];
if (hits.length >= LIMIT_PER_IP) {
  return reply({ ok: false, error: 'rate_limited', message: 'Too many price lookups. Try again in a few minutes.', fallback: true });
}
hits.push(now);
store.hits[ip] = hits;

// Validate input.
const clean = (s, max) => String(s == null ? '' : s)
  .replace(/[\u0000-\u001f<>]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, max);

const destination = clean(body.destination, 80);
if (destination.length < 2) {
  return reply({ ok: false, error: 'bad_request', message: 'destination is required' });
}

let activities = body.activities;
if (!Array.isArray(activities)) activities = activities ? [activities] : [];
activities = activities.map((a) => clean(a, 40)).filter(Boolean).slice(0, 3);

const cur = String(body.currency || '').toUpperCase();
const currency = CURRENCIES.includes(cur) ? cur : 'USD';

let limit = parseInt(body.limit, 10);
if (!(limit >= 1 && limit <= 12)) limit = 6;

const searchTerm = [destination].concat(activities).join(' ');
const cacheKey = [searchTerm.toLowerCase(), currency, limit].join('|');

// Serve from cache.
const hit = store.cache[cacheKey];
if (hit) {
  return reply(Object.assign({}, hit.payload, { cached: true }));
}

// Keep the cache bounded: drop the oldest entries.
const keys = Object.keys(store.cache);
if (keys.length >= CACHE_MAX) {
  keys.sort((a, b) => store.cache[a].at - store.cache[b].at)
    .slice(0, keys.length - CACHE_MAX + 1)
    .forEach((k) => delete store.cache[k]);
}

return [{
  json: {
    cacheKey,
    destination,
    currency,
    viatorBody: {
      searchTerm,
      currency,
      searchTypes: [{ searchType: 'PRODUCTS', pagination: { start: 1, count: limit } }],
    },
  },
}];

// Turn Viator's /search/freetext response into the small shape the site uses.
// Field names are read defensively: anything missing becomes null, and a
// product without a title, a viator.com link or a price is dropped.
const res = $input.first().json || {};
const prev = $('Validate & Check Cache').first().json;
const store = $getWorkflowStaticData('global');
store.cache = store.cache || {};
const reply = (response) => [{ json: { response } }];

// The HTTP node runs with "continue on error", so failures arrive as { error }.
if (res.error || !res.products) {
  return reply({ ok: false, error: 'upstream', message: 'Live tour prices are unavailable right now.', fallback: true });
}

const num = (v) => (typeof v === 'number' && isFinite(v) ? v : null);

function pickImage(p) {
  const imgs = Array.isArray(p.images) ? p.images : [];
  const cover = imgs.find((i) => i && i.isCover) || imgs[0];
  const variants = cover && Array.isArray(cover.variants) ? cover.variants : [];
  let best = null;
  for (const v of variants) {
    if (!v || !v.url || !(v.width >= 300 && v.width <= 900)) continue;
    if (!best || Math.abs(v.width - 600) < Math.abs(best.width - 600)) best = v;
  }
  if (!best) best = variants.find((v) => v && v.url) || null;
  return best ? safeUrl(best.url, /(^|\.)(viator|tripadvisor)\.com$|(^|\.)tacdn\.com$/) : null;
}

function durationText(d) {
  if (!d) return null;
  const fmt = (m) => (m >= 60 ? Math.round(m / 6) / 10 + ' h' : m + ' min');
  const fixed = num(d.fixedDurationInMinutes);
  const from = num(d.variableDurationFromMinutes);
  const to = num(d.variableDurationToMinutes);
  if (fixed) return fmt(fixed);
  if (from && to) return fmt(from) + '–' + fmt(to);
  if (from) return fmt(from);
  return null;
}

// Only pass through https links on hosts we expect.
function safeUrl(u, hostPattern) {
  try {
    const x = new URL(String(u));
    return x.protocol === 'https:' && hostPattern.test(x.hostname) ? x.toString() : null;
  } catch (e) {
    return null;
  }
}

const results = Array.isArray(res.products.results) ? res.products.results : [];
const products = results.map((p) => {
  const pricing = p.pricing || {};
  const summary = pricing.summary || {};
  const reviews = p.reviews || {};
  return {
    code: String(p.productCode || ''),
    title: String(p.title || '').slice(0, 160),
    fromPrice: num(summary.fromPrice),
    fromPriceBeforeDiscount: num(summary.fromPriceBeforeDiscount),
    currency: String(pricing.currency || prev.currency),
    rating: num(reviews.combinedAverageRating),
    reviewCount: num(reviews.totalReviews),
    duration: durationText(p.duration),
    image: pickImage(p),
    url: safeUrl(p.productUrl, /(^|\.)viator\.com$/),
  };
}).filter((p) => p.code && p.title && p.url && p.fromPrice != null);

const response = {
  ok: true,
  source: 'viator',
  priceType: 'live',
  fetchedAt: new Date().toISOString(),
  destination: prev.destination,
  currency: prev.currency,
  products,
};

if (products.length) store.cache[prev.cacheKey] = { at: Date.now(), payload: response };
return reply(response);
